-- Linha de gestão da Camilla nos roteiros de cobrança (Dar retorno): auto-responsabilidade e maturidade do time.
-- Ordem: problema com número (na segunda pessoa) → o que ela já faz bem ({forca}, a força do perfil) →
-- solução mostrada na prática → dificuldade de execução → o combinado sai dela. Tira o "balcão" que restava.
update metodo set dados = jsonb_set(jsonb_set(jsonb_set(dados,
 '{modelos,cobranca_querer}', $j$["Cobrança na linha de gestão · no particular, com número, na semana.", "", "1. O problema, com número: \"{nome}, combinamos {combinado}. {aconteceu}.\" (sempre na segunda pessoa: é ela quem muda o número)", "2. Impacto: \"{impacto}\"", "3. O que você já faz bem: \"{forca}\" (pontue a força dela antes de pedir a mudança)", "4. A solução, mostrada: demonstre com um exemplo real como fazer, no atendimento.", "5. A dificuldade: \"O que te impediu? O que pode atrapalhar de fazer isso?\" (se a resposta for \"não sei fazer\", a cobrança vira treino)", "6. O combinado sai dela: \"O que você vai fazer, quanto e até quando?\" Sugestão: \"{novo}\"", "7. Retorno: \"{retorno} a gente olha junto.\"", "", "Lembre: cobrança é sobre o combinado, não sobre a pessoa. Nunca no grupo nem na frente de cliente.", "{@tom}"]$j$::jsonb),
 '{modelos,cobranca_poder}', $j$["Diagnóstico: falta PODER. {nome} quer, mas não consegue. Tire o obstáculo e dê a ferramenta antes de cobrar.", "", "1. O problema, com número: \"{nome}, combinamos {combinado}. {aconteceu}.\"", "2. O que você já faz bem: \"{forca}\"", "3. A dificuldade: \"O que está te impedindo? Do que você precisa para conseguir?\"", "4. Obstáculo: anote o que {nome} disser e resolva o que é seu (tempo, ferramenta, lista, acesso).", "5. O combinado sai dela: \"O que você vai fazer, quanto e até quando?\" Sugestão: \"{novo}\"", "6. Retorno: \"{retorno} a gente olha junto.\"", "{@tom}"]$j$::jsonb),
 '{modelos,cobranca_saber}', $j$["Diagnóstico: falta SABER. Cobrar quem não sabe gera medo: aqui o caminho é ensinar.", "", "Antes: mostre o problema com número (\"{nome}, você está...\") e o que ela já faz bem: \"{forca}\"", "", "Ensinar em 4 passos, uma coisa por vez:", "1. Eu faço, você vê: mostre para {nome} como fazer \"{combinado}\".", "2. Fazemos juntos: no salão, com cliente real ou numa simulação de 10 minutos antes de abrir.", "3. Você faz, eu vejo: corrija com calma, sem plateia. Pergunte o que está difícil.", "4. Você faz sem ajuda: {novo_saber} (o combinado sai dela) e olhe junto {retorno_saber}.", "{@tom}"]$j$::jsonb)
where chave = 'pessoas';

-- A mesma linha nas instruções do agente da leitura da semana.
update metodo set dados = jsonb_set(dados, '{instrucoes}', to_jsonb((dados->>'instrucoes') || E'\n\nLinha de gestão da Camilla (auto-responsabilidade e maturidade do time): fale sempre com a responsabilidade com quem faz. "O time está vendendo as peças mais baratas", "a Larissa está vendendo com uma peça só", nunca "as clientes estão levando". Quando sugerir conversa com uma vendedora, a ordem é: o problema com número, o que ela já faz bem (a força do perfil), a solução mostrada na prática, a dificuldade e o combinado que sai dela.'))
where chave = 'leitura_agente' and position('Linha de gestão da Camilla' in dados->>'instrucoes') = 0;
